WITH "r0" AS ( SELECT "s".* FROM "public"."revision" AS "s" WHERE true AND ( EXISTS (SELECT 1 FROM "public"."article" AS "e0" WHERE true AND "e0"."id" = "s"."article_id" AND "e0"."author_id" = "s"."author_id" AND ( "e0"."id" = $1 )) ) ORDER BY "s"."note" ASC NULLS LAST ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."note" AS "note" ) AS "%")) ORDER BY "t0"."note" ASC NULLS LAST ), '[]') FROM "r0" AS "t0"
